const GRAIN_IMAGE =
  "data:image/png;base64,";

interface ArtBlobProps {
  tone: ArtTone;
  shape?: number;
  className?: string;
}

/**
 * A painted pastel shape: a solid fill, flecked with a deeper shade of the
 * same hue so it reads as brushed paper rather than a flat vector. Colours
 * come from the tone class and follow the theme.
 */
export const ArtBlob = ({ tone, shape = 0, className }: ArtBlobProps) => {
  const uid = useId().replace(/:/g, "");
  const patternId = `tk-grain-${uid}`;
  const maskId = `tk-grain-mask-${uid}`;
  const d = BLOB_PATHS[shape % BLOB_PATHS.length];

  return (
    <svg
      viewBox="0 0 600 500"
      className={`${styles.blob} ${styles[tone]} ${className ?? ""}`.trim()}
      aria-hidden="true"
      focusable="false"
    >
      <defs>
        <pattern id={patternId} patternUnits="userSpaceOnUse" width="192" height="192">
          <image href={GRAIN_IMAGE} width="192" height="192" />
        </pattern>
        <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="600" height="500">
          <rect width="600" height="500" fill={`url(#${patternId})`} />
        </mask>
      </defs>
      <path d={d} className={styles.fill} />
      <path d={d} className={styles.grain} mask={`url(#${maskId})`} />
    </svg>
  );
};

export type DoodleKind = "sparkle" | "burst" | "squiggle" | "asterisk" | "swoosh" | "arrow" | "star";

const DOODLES: Record<DoodleKind, { viewBox: string; paths: string[] }> = {
  sparkle: {
    viewBox: "0 0 48 48",
    paths: ["M24 5c1.4 9.6 5.4 14.1 17 16.4-11.6 2.4-15.6 6.6-17 18.6-1.6-12-5.6-16.2-17.2-18.6C18.4 19.1 22.4 14.6 24 5Z"],
  },
  burst: {
    viewBox: "0 0 48 48",
    paths: ["M6 31.5 18.5 28", "M9.5 15.5l10.6 7.4", "M23 5.5l3.2 12.8"],
  },
  squiggle: {
    viewBox: "0 0 96 28",
    paths: ["M4 18c7-12 14-12 18 0s11 12 18 0 14-12 18 0 11 12 18 0 10-11 16-4"],
  },
  asterisk: {
    viewBox: "0 0 48 48",
    paths: ["M24.5 6.5c-.6 11.6-.2 23.2.8 35", "M8 17.5c10.6 4.2 21.6 8.6 32.6 13.4", "M9.4 33c9.8-6.6 20-12.4 30.4-17.6"],
  },
  swoosh: {
    viewBox: "0 0 240 26",
    paths: ["M5 17c44-9.5 98-13 150-10.5 28 1.4 52 4.4 80 9.5", "M40 22.5c46-4.8 100-5.6 152-.6"],
  },
  arrow: {
    viewBox: "0 0 96 64",
    paths: ["M6 10c8 26 30 42 64 34 4.6-1.1 9.2-2.8 13.6-5", "M71.6 31.4 84 38.8l-12 7.4"],
  },
  star: {
    viewBox: "0 0 48 48",
    paths: [
      "M24 6.5l5.2 11.4 12.3 1.4-9.2 8.5 2.6 12.2L24 33.8l-10.9 6.2 2.6-12.2-9.2-8.5 12.3-1.4Z",
      "M10.5 7.5 6 4.5",
      "M38.4 7.2 42.5 4",
      "M42.5 40.5 46 44",
    ],
  },
};

interface DoodleProps {
  kind: DoodleKind;
  className?: string;
}

/** A hand-drawn stroke mark in currentColor; purely decorative. */
export const Doodle = ({ kind, className }: DoodleProps) => {
  const { viewBox, paths } = DOODLES[kind];
  return (
    <svg
      viewBox={viewBox}
      className={`${styles.doodle} ${className ?? ""}`.trim()}
      aria-hidden="true"
      focusable="false"
    >
      {paths.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
};
